messages.content:
Tool response:
Tool: create_refill_order
Description: Create Refill Order
Parameters:
    {
      "type": "object",
      "properties": {
        "prescription_id": {
          "type": "integer",
          "title": "Prescription Id",
          "description": "Internal ID of the prescription to refill"
        },
        "quantity": {
          "type": "integer",
          "title": "Quantity",
          "description": "Number of tablets to refill"
        },
        "pharmacy_id": {
          "type": "integer",
          "title": "Pharmacy Id",
          "description": "Internal ID of the pharmacy where pickup will occur"
        },
        "pickup_type": {
          "type": "string",
          "title": "Pickup Type",
          "description": "Type of pickup method (in-store, drive-thru, delivery)",
          "default": "in-store"
        }
      },
      "required": [
        "prescription_id",
        "quantity",
        "pharmacy_id"
      ]
    }
